import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, relative, resolve } from "node:path";
import { Fail } from "./errors.js";
import { type WarnOptions, warn } from "./ui/warn.js";

/**
 * The phrase a generated file carries, and the one thing `write` looks for to tell a file
 * it produced from one somebody wrote by hand.
 */
export const GENERATED = "Generated by envy";

export type WriteOptions = WarnOptions & {
  /** What a relative path is resolved against. Defaults to the current directory. */
  cwd?: string;
};

export type WriteResult = {
  path: string;
  /** `false` when the file already held exactly this, so nothing was touched. */
  changed: boolean;
};

/**
 * Write a file. The only thing in envy that touches disk, apart from the config file the
 * store owns.
 *
 * A file that already holds exactly this content is left alone, so a second run of a setup
 * script changes nothing at all: no new mtime, no watcher waking up, no diff.
 *
 * A format returns a string and nothing else, so anything can be written here, including a
 * renderer of the caller's own. That is also why the warning below checks the content
 * rather than the extension: envy has no idea what kind of file this is, only whether it
 * looks like one it produced.
 */
export async function write(
  path: string,
  content: string,
  options: WriteOptions = {},
): Promise<WriteResult> {
  const target = resolve(options.cwd ?? process.cwd(), path);

  let existing: string | undefined;

  try {
    existing = await readFile(target, "utf8");
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== "ENOENT") {
      throw new Fail(`${path} could not be read: ${(error as Error).message}`);
    }
  }

  if (existing === content) return { path: target, changed: false };

  if (existing !== undefined && !existing.includes(GENERATED) && content.includes(GENERATED)) {
    warn(
      {
        title: `${relative(options.cwd ?? process.cwd(), target) || path} was not written by envy and is about to be.`,
        detail: [
          "Whatever is in it now will be gone. If you meant to keep it, stop and copy it",
          "somewhere first: from here on, this file is generated.",
        ],
        key: `overwrite:${target}`,
      },
      options,
    );
  }

  try {
    await mkdir(dirname(target), { recursive: true });
    await writeFile(target, content, "utf8");
  } catch (error) {
    throw new Fail(`${path} could not be written: ${(error as Error).message}`);
  }

  return { path: target, changed: true };
}
